export function buildPikachuFairWithAuthoredHurtboxes(): AerialMove {
  const hurtboxModifiers: MoveHurtboxModifier[] = PIKACHU_FAIR_AUTHORED_HURTBOX_POSES.flatMap(row =>
    row.hurtboxes.map(hurtbox => ({ frameWindow: { startFrame: row.startElapsed, endFrame: row.endElapsed },
      replaceBody: true, hurtbox })));
  return { ...buildPikachuNormalMove('forward-air', undefined, { rehitClockPolicy: 'authored-attack-elapsed' }),
    hurtboxModifiers } as AerialMove & AttackMoveWithAnimation;
}
